from itertools import combinations, product


def _build_quota_solver(capacity, tie):
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for chosen in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in chosen))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in chosen:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            points = []
            for job in chosen:
                points.append((job["start"], 1))
                points.append((job["end"], -1))
            active = 0
            feasible = True
            for _, delta in sorted(points):
                active += delta
                if active > capacity:
                    feasible = False
                    break
            if not feasible:
                continue

            value = sum(job["value"] for job in chosen)
            if (best_ids is None or value > best_value or
                    (value == best_value and
                     (ids > best_ids if tie == "largest" else ids < best_ids))):
                best_ids, best_value = ids, value

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            allowed = [row for row in packages[name]
                       if row["version"] not in blocked.get(name, []) and
                       (name not in pins or row["version"] == pins[name])]
            choices.append([None] + allowed)

        best_vector = None
        best_install = None
        for assignment_rows in product(*choices):
            assignment = {name: row for name, row in zip(names, assignment_rows)
                          if row is not None}

            valid = True
            for name, (low, high) in roots.items():
                row = assignment.get(name)
                if row is None or not low <= row["version"] <= high:
                    valid = False
                    break
            if not valid:
                continue

            edges = {}
            for name, row in assignment.items():
                deps = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = assignment.get(dep["name"])
                    if other is None or not dep["min"] <= other["version"] <= dep["max"]:
                        valid = False
                        break
                    deps.append(dep["name"])
                if not valid:
                    break
                edges[name] = deps
            if not valid:
                continue

            # The installed packages must be exactly the active closure of roots.
            closure = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in closure:
                    continue
                if name not in assignment:
                    valid = False
                    break
                closure.add(name)
                pending.extend(edges.get(name, []))
            if not valid or closure != set(assignment):
                continue

            finished = set()
            active = set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in assignment):
                continue

            vector = tuple(assignment[name]["version"] if name in assignment else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_install = {name: assignment[name]["version"]
                                for name in names if name in assignment}

        if best_install is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_install}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        indexes = {node: i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1

        def add_visit(mask, node):
            index = indexes.get(node)
            return mask if index is None else mask | (1 << index)

        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start = data["start"]
        initial_mask = add_visit(0, source)
        coupons = data["coupons"]
        initial = (source, initial_mask, coupons)
        distances = {initial: start}
        queue = [(start, source, initial_mask, coupons)]

        while queue:
            arrival, node, mask, left = heapq.heappop(queue)
            state = (node, mask, left)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full and left == 0:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                next_node = edge["v"]
                next_mask = add_visit(mask, next_node)
                durations = [(edge["duration"], left)]
                if left:
                    durations.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
                for duration, next_left in durations:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, next_left)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask, next_left))

        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_quota_solver(2, "largest"),
    "component_02": _build_quota_solver(1, "smallest"),
    "component_03": _build_quota_solver(2, "smallest"),
    "component_04": _build_quota_solver(1, "largest"),
    "component_05": _build_quota_solver(2, "largest"),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
